<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Database\Eloquent\Relations\HasOne;
class Job extends Model{protected $table='job_postings';protected $fillable=['company_id','quotation_id','created_by','slug','title','summary','description','requirements','benefits','location','modality','contract_type','salary_text','salary_min','salary_max','currency','status','quality_score','quality_issues','review_note','submitted_at','published_at','expires_at'];protected function casts():array{return ['requirements'=>'array','benefits'=>'array','quality_issues'=>'array','submitted_at'=>'datetime','published_at'=>'datetime','expires_at'=>'datetime'];}public function company():BelongsTo{return $this->belongsTo(Company::class);}public function applications():HasMany{return $this->hasMany(JobApplication::class);}public function payment():HasOne{return $this->hasOne(PaymentOrder::class);}public function quotation():BelongsTo{return $this->belongsTo(Quotation::class);}}
